import{_ as a,o as t,c as r,a0 as d}from"./chunks/framework.K3sFe4KB.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"cicada","text":"Calendars as code","tagline":"The bug that shows up on time. Declare calendars in YAML; plan, apply, and detect drift like infrastructure — with an MCP server so agents can too.","actions":[{"theme":"brand","text":"Get started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Reference","link":"/reference/cli"}]},"features":[{"title":"Declarative YAML DSL","details":"Events, recurrence, attendees, conferencing, and reminders declared as code — a Kubernetes-style apiVersion/kind envelope, validated before anything touches a provider."},{"title":"Plan / apply / drift","details":"Desired vs recorded vs live state, diffed into ordered create/update/delete/replace operations. Apply is sequenced, idempotent, resumable, and never deletes what it didn't create."},{"title":"MCP for agents, day one","details":"tamias-driver-cicada mcp renders the engine ops manifest as MCP tools — agents read, preview, and reconcile calendars through the same verbs, gated by the planDigest contract."},{"title":"Provider-agnostic by construction","details":"Ports-and-adapters: Google Calendar today (Meet included), more providers behind the same CalendarProvider port. Capabilities are checked at plan time, never silently dropped."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),n={name:"index.md"};function o(i,e,s,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[d('<h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Cicada is calendars as code: declare calendars in YAML (<code>apiVersion: cicada/v1</code>), then <code>plan</code>/<code>apply</code>/<code>drift</code> against live providers the way you manage infrastructure. The <code>cicada</code> command is a tamias pack; <code>tamias-driver-cicada</code> exposes the same engine as ops, a <code>cli</code> shim, and an MCP surface for agents.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Calendar APIs aren&#39;t transactional and export-only tools can&#39;t map stable ids to remote ids — re-runs duplicate. Cicada keeps three states (desired YAML, recorded <code>.cicada/state.yaml</code>, live provider) and reconciles them with ordered, idempotent, resumable ops under a managed boundary that never touches events it didn&#39;t create.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> the desired-state lifecycle — declare, plan, apply, drift, refresh — and the provider/state/auth ports.</li><li><strong>Doesn&#39;t own:</strong> the calendar providers themselves (Google Calendar API), secrets (<a href="https://9aia.com/cuora/" target="_blank" rel="noreferrer">cuora</a>), distribution (<a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a>), orchestration (<a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a>).</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Reconcile a calendar end to end</td><td><a href="/cicada/tutorials/getting-started.html">Tutorial</a></td></tr><tr><td>Do a task (Google auth, recurrence, CI, agent use)</td><td><a href="/cicada/how-to/">How-to</a></td></tr><tr><td>Understand the design (ports, reconciliation, landscape)</td><td><a href="/cicada/explanation/">Explanation</a></td></tr><tr><td>Look up a verb, YAML field, or state shape</td><td><a href="/cicada/reference/">Reference</a></td></tr></tbody></table>',8)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
